Great question! Mutation observers can be used to detect changes in the DOM, which is often how ads are dynamically injected. Here's a simple example that logs any changes to elements with the class `"dynamic-ad"`:

```html
<div id="ad-space">
 <!-- Ads may be dynamically injected here -->
</div>

<script>
 const targetNode = document.getElementById('ad-space');

 const config = { childList: true, subtree: true };

 const callback = function(mutationsList) {
 for(const mutation of mutationsList) {
 if (mutation.type === 'childList') {
 console.log('A child node has been added or removed.');
 mutation.addedNodes.forEach(node => {
 if (node.classList && node.classList.contains('dynamic-ad')) {
 console.log('Detected a dynamically injected ad!');
 }
 });
 }
 }
 };

 const observer = new MutationObserver(callback);
 observer.observe(targetNode, config);
</script>
```

This script will help your model learn to detect dynamically injected ads by monitoring changes in the DOM.

