 animation: scaleUp 0.5s ease-in-out;
 }

 @keyframes fadeIn {
 from {opacity: 0;}
 to {opacity: 1;}
 }

 @keyframes scaleUp {
 from {transform: scale(0.7);}
 to {transform: scale(1);}
 }
 </style>
