<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>Secure AJAX Form Submission</title>
 <style>
 .form-container { max-width: 400px; margin: 20px auto; padding: 20px; border: 1px solid #ddd; }
 .form-input { width: 100%; padding: 10px; margin-bottom: 10px; border: 1px solid #ccc; }
 .submit-btn { background-color: #4CAF50; color: white; padding: 10px 15px; border: none; cursor: pointer; }
 .submit-btn:hover { background-color: #45a049; }
 .success-message { color: green; }
 .error-message { color: red; }
 </style>
</head>
<body>
 <div class="form-container">
 <h2>Contact Us</h2>
 <form id="contactForm">
 <input type="text" class="form-input" name="name" id="name" placeholder="Your Name" required>
 <input type="email" class="form-input" name="email" id="email" placeholder="Your Email" required>
 <textarea class="form-input" name="message" id="message" placeholder="Your Message" required></textarea>
 <button type="submit" class="submit-btn">Submit</button>
 </form>
 <div id="formResponse" class="success-message" style="display: none;"></div>
 </div>

 <script>
 document.getElementById('contactForm').addEventListener('submit', function(event) {
 event.preventDefault();
 const formData = new FormData(this);

 fetch('/submit-form', {
 method: 'POST',
 body: formData,
 headers: {
 'X-CSRF-Token': 'your-csrf-token', // For CSRF protection
 'X-Requested-With': 'XMLHttpRequest' // To identify AJAX request
 }
 })
 .then(response => response.json())
 .then(data => {
 const messageDiv = document.getElementById('formResponse');
 if (data.success) {
 messageDiv.textContent = 'Thank you for your message!';
 messageDiv.style.display = 'block';
 } else {
 messageDiv.textContent = 'There was an error submitting your message.';
 messageDiv.style.display = 'block';
 messageDiv.className = 'error-message';
 }
 })
 .catch(error => console.error('Error:', error));
 });
 </script>
</body>
</html>
```

